        try:
            next(klasses)  
            parent = next(klasses)
        except StopIteration:
            raise NotImplementedError(f"Unsupported renderer {type(r)}") from None
        else:
            return getattr(parent, self.name)(r, element)

    @overload
    def __get__(self: D, obj: None, owner: type) -> D: ...

